  select user_id into v_admin from public.user_roles where role = 'system_admin' order by created_at limit 1;
  if v_admin is null then raise exception 'Cần có ít nhất 1 tài khoản system_admin trước khi nạp bài tập'; end if;
  if exists (select 1 from public.lessons where content ->> 'seed_id' = 'ta4-gs-u15') then return; end if;
  select s.id, 'Unit 15. My family''s weekends', '{"seed_id":"ta4-gs-u15","kind":"book","book":"Global Success","ref":"Unit 15","unit_code":"GS4.P3","unit_title":"Học kì 2 · Unit 11–15","description":"Cuối tuần của gia đình tớ. Từ vựng: cinema, shopping centre, swimming pool, sports centre, bookshop, weekend. Mẫu câu: Where do you go at the weekend? – I go to the cinema. / What does your father do at the weekend? – He goes to the swimming pool."}'::jsonb, 'review', v_admin, 'Global Success', 2, 125, (select id from public.curriculum_topics where code = 'A4.LANG')
  from public.subjects s where s.code = 'tieng-anh-4' returning id into v_lesson;
end $$;

