  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Người bác sĩ làng\":\nBác sĩ Tâm về làm việc ở trạm y tế xã đã hai mươi năm. Ngày cũng như đêm, hễ có người ốm là bác đến ngay. Có đêm mưa lớn, bác lội qua con suối đang dâng nước để kịp cấp cứu cho một em bé. Với những gia đình khó khăn, bác thường khám bệnh và cho thuốc không lấy tiền. Người dân trong xã gọi bác là \"người thầy thuốc như mẹ hiền\".\n\nBác sĩ Tâm làm việc ở đâu?"}'::jsonb, '["trạm y tế xã","bệnh viện tỉnh","nhà thuốc"]'::jsonb, null, 1, 40, 1, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V4.DOC.01')) returning id into v_q;
