  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Ông Bụt của bé Na\":\nNhà bé Na nghèo, Tết năm ấy không có tiền mua quần áo mới. Na buồn lắm. Sáng mùng Một, trước cửa nhà có một gói quà. Trong gói có chiếc áo đỏ và tấm thiệp: \"Chúc bé Na một năm mới vui vẻ.\" Na reo lên: \"Ông Bụt đã đến!\" Mãi về sau Na mới biết người gửi quà là cô hàng xóm. Cô đã thức mấy đêm liền để may chiếc áo cho Na.\n\nVì sao Tết năm ấy Na buồn?"}'::jsonb, '["vì không có quần áo mới","vì bị ốm","vì không được đi chơi"]'::jsonb, null, 1, 40, 1, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V4.DOC.01')) returning id into v_q;
