  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Khóm tre đầu ngõ\":\nĐầu ngõ nhà em có một khóm tre xanh. Mùa hè, khóm tre toả bóng mát cho người qua đường nghỉ chân. Chiều chiều, chim sẻ, chim chào mào về ríu rít trên ngọn tre. Một năm nọ, cặp cò trắng làm tổ trên khóm tre. Cả xóm dặn nhau không ai được làm kinh động. Mấy tuần sau, những chú cò con chui ra khỏi vỏ trứng. Khóm tre như một ngôi nhà chung bình yên.\n\nMùa hè, khóm tre làm gì cho người qua đường?"}'::jsonb, '["toả bóng mát","chắn gió","cho măng"]'::jsonb, null, 1, 40, 1, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V4.DOC.01')) returning id into v_q;
