  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Vườn cây của ông\":\nỞ cuối làng, ông tôi có một khu vườn rộng. Ngày còn trẻ, ông tự tay trồng từng gốc nhãn, gốc vải. Mùa hè, quả chín sai trĩu cành. Mỗi lần con cháu về, ông lại dắt đi khắp vườn, kể cây nào trồng năm nào. Ông bảo: \"Cây cũng như người, phải chăm sóc mới lớn.\" Bây giờ, chúng tôi thay ông chăm vườn, để khu vườn mãi xanh tươi như tấm lòng của ông.\n\nKhu vườn của ông ở đâu?"}'::jsonb, '["ở cuối làng","ở giữa phố","trên đồi"]'::jsonb, null, 1, 40, 1, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V4.DOC.01')) returning id into v_q;
