  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Thầy giáo của bố\":\nNhân ngày Nhà giáo, bố dẫn tôi đến thăm thầy giáo cũ của bố. Thầy đã già, tóc bạc trắng. Vừa thấy thầy, bố vội vàng bỏ mũ, kính cẩn chào. Bố kể: \"Nhờ thầy dạy dỗ, bố mới nên người.\" Thầy cười hiền, nhắc lại chuyện ngày xưa bố hay trốn học đi bắt dế. Để giữ lời hứa với thầy, bố đã chăm chỉ học và trở thành kĩ sư. Tôi hiểu thêm về lòng biết ơn thầy cô.\n\nTrạng ngữ \"Nhờ thầy dạy dỗ\" chỉ gì?"}'::jsonb, '["nguyên nhân","mục đích","thời gian"]'::jsonb, null, 3, 60, 5, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V4.DOC.02')) returning id into v_q;
