  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Chiếc khăn quàng đỏ\":\nNgày Minh được kết nạp Đội, mẹ là ngực áo cho Minh thật phẳng. Ông nội trao cho Minh chiếc khăn quàng đỏ cũ mà ông đã giữ từ thời còn là đội viên. Ông dặn: \"Khăn quàng là một phần lá cờ Tổ quốc. Cháu phải học giỏi, ngoan ngoãn để xứng đáng với màu đỏ ấy.\" Trong buổi lễ, Minh đứng thẳng, giơ tay chào. Lòng cậu rộn ràng niềm tự hào.\n\nAi trao khăn quàng đỏ cho Minh?"}'::jsonb, '["ông nội","cô giáo","mẹ"]'::jsonb, null, 1, 40, 1, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V4.DOC.01')) returning id into v_q;
