  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Chuyến đò về quê ngoại\":\nHè này, Mai theo mẹ về quê ngoại bằng chuyến đò dọc. Hai bên sông, những bãi ngô xanh mướt trải dài. Bác lái đò vừa chèo vừa hát câu hò quen thuộc. Mẹ bảo đó là điệu \"hò mái đẩy\" của quê mình. Mai thích thú lắng nghe. Lúc đò cập bến, bà ngoại đã đứng chờ dưới gốc gạo. Bà ôm Mai vào lòng: \"Cháu bà lớn quá rồi!\"\n\nMai về quê ngoại bằng phương tiện gì?"}'::jsonb, '["đò","ô tô","tàu hoả"]'::jsonb, null, 1, 40, 1, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V4.DOC.01')) returning id into v_q;
