  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Chuyến đi Sa Pa\":\nĐội Thiếu niên Tiền phong của trường tổ chức cho chúng em đi Sa Pa. Xe leo dốc quanh co, mây trắng bay vờn ngang cửa kính. Hai bên đường, những thửa ruộng bậc thang như những bậc thang khổng lồ dẫn lên trời. Chúng em ghé thăm Trường Tiểu học Bản Hồ, tặng các bạn nhỏ vùng cao sách vở và áo ấm. Các bạn tặng lại chúng em những chiếc túi thổ cẩm xinh xắn.\n\nAi tổ chức chuyến đi Sa Pa?"}'::jsonb, '["Đội Thiếu niên Tiền phong của trường","gia đình em","công ty du lịch"]'::jsonb, null, 1, 40, 1, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V4.DOC.01')) returning id into v_q;
