  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Khu rừng của voọc\":\nỞ Vườn quốc gia Cúc Phương có một trung tâm cứu hộ những chú voọc bị thương. Các cô chú nhân viên chăm sóc chúng tận tình như chăm con nhỏ. Khi voọc khoẻ lại, các cô chú đưa chúng trở về rừng. Lần đầu được thả, chú voọc nhỏ ngập ngừng, rồi nhanh nhẹn chuyền cành, mất hút giữa tán lá xanh. Nhìn theo, cô Hằng mỉm cười hạnh phúc.\n\nTrung tâm cứu hộ ở đâu?"}'::jsonb, '["Vườn quốc gia Cúc Phương","sở thú thành phố","trên đảo"]'::jsonb, null, 1, 40, 1, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V4.DOC.01')) returning id into v_q;
