  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Nhà của chú gấu Bắc Cực\":\nGấu trắng sống ở vùng Bắc Cực lạnh giá. Chúng săn mồi trên những tảng băng lớn. Nhưng Trái Đất đang nóng lên, băng tan dần. Nhiều chú gấu phải bơi rất xa mới tìm được chỗ nghỉ chân. Các nhà khoa học kêu gọi mọi người tiết kiệm điện, trồng thêm cây xanh, hạn chế xả rác để giảm khí thải. Những việc nhỏ của chúng ta có thể giữ lại ngôi nhà băng cho gấu trắng.\n\nGấu trắng sống ở đâu?"}'::jsonb, '["vùng Bắc Cực","rừng nhiệt đới","sa mạc"]'::jsonb, null, 1, 40, 1, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V4.DOC.01')) returning id into v_q;
