  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Ngày hội hữu nghị\":\nTrường em tổ chức \"Ngày hội hữu nghị\" với các bạn học sinh đến từ nhiều nước. Bạn Yu-ki (Nhật Bản) hướng dẫn chúng em gấp hạc giấy. Bạn An-na (Nga) dạy cả lớp một điệu múa vòng tròn. Chúng em giới thiệu với các bạn món bánh chưng và trò chơi kéo co. Cuối ngày, mọi người cùng hát vang:\n– Trái Đất này là của chúng mình!\nTiếng hát vang xa như một lời chúc hoà bình.\n\nBạn Yu-ki hướng dẫn các bạn làm gì?"}'::jsonb, '["gấp hạc giấy","múa vòng tròn","gói bánh chưng"]'::jsonb, null, 1, 40, 1, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V4.DOC.01')) returning id into v_q;
